// === USER-DEFINED MAPPING POINTS ===
#define MAX_PRESETS 3
#define POINTS 21

struct ServoMap {
  float rollInput[POINTS];
  float pitchInput[POINTS];
  float rollToRight[POINTS];
  float pitchToRight[POINTS];
  float rollToLeft[POINTS];
  float pitchToLeft[POINTS];
};

const int trigPins[3] = {27, 25, 32};   // left = D18, middle = TX2, right = D4
const int echoPins[3] = {14, 26, 33};   // left = D19, middle = D5, right = RX2

const int numSensors = sizeof(trigPins) / sizeof(trigPins[0]);

const int remoteOnPin = 23;
const int remoteOffPin = 22;
const int motorDriverEnablePin = 18;
const int motorDriverEnabledState = HIGH;
const int motorDriverDisabledState = LOW;

const int edgeSensorPins[2] = {13, 39};  // 0 = front-left, 1 = front-right
const int edgeSensorDetectedState = LOW;  // white edge detected, black field clear
const int edgeConfirmSamples = 2;
const unsigned long edgeReverseDuration = 500;

const int R_IN1 = 4;
const int R_IN2 = 16;
const int L_IN1 = 21;
const int L_IN2 = 19;

const int defaultRobotSpeed = 255;

#define SOUND_SPEED 0.034
#define DETECTION_THRESHOLD 40.0

const uint8_t MOTOR_FORWARD_PIN = 19;
const uint8_t MOTOR_REVERSE_PIN = 21;

const uint32_t MOTOR_RUN_MS = 60000;
const uint32_t PWM_FREQUENCY = 20000;
const uint8_t PWM_RESOLUTION_BITS = 10;
const uint16_t PWM_MAX_DUTY = (1 << PWM_RESOLUTION_BITS) - 1;
const uint8_t PWM_FORWARD_CHANNEL = 0;
const uint8_t PWM_REVERSE_CHANNEL = 1;

// Detection timing.
static constexpr uint32_t SENSOR_SAMPLE_MS = 20;
static constexpr uint32_t MPU_SAMPLE_MS = 100;
static constexpr uint32_t STATUS_PRINT_MS = 2000;
static constexpr uint32_t WIFI_CONNECT_TIMEOUT_MS = 20000;
static constexpr uint32_t WIFI_RECONNECT_MS = 30000;
static constexpr uint32_t IR_FRAME_PERIOD_MS = 110;
static constexpr uint32_t BEAM_BREAK_CONFIRM_MS = 350;
static constexpr uint32_t TAMPER_CONFIRM_MS = 250;

// Tamper thresholds. Tune after observing normal mounting vibration.
static constexpr float TAMPER_TILT_DEGREES = 30.0f;
static constexpr float TAMPER_GYRO_DPS = 180.0f;
static constexpr float TAMPER_ACCEL_DELTA_G = 0.65f;

constexpr uint8_t LOADCELL_DOUT_PIN = 5;
constexpr uint8_t LOADCELL_SCK_PIN = 18;
constexpr uint8_t HX711_GAIN = 128;  // Channel A, gain 128.

constexpr char BLE_DEVICE_NAME[] = "GYM-Scale";
constexpr char SCALE_SERVICE_UUID[] = "7e57c000-6f7a-4b64-9c98-7fdc2d2f7c01";
constexpr char MEASUREMENT_CHARACTERISTIC_UUID[] = "7e57c001-6f7a-4b64-9c98-7fdc2d2f7c01";

// Calibrate this with a known mass. If weight moves negative when loaded,
// either make this value negative or swap A+ and A- on the HX711.
constexpr float CALIBRATION_COUNTS_PER_GRAM = 420.0f;
constexpr float LOAD_CELL_CAPACITY_GRAMS = 10000.0f;

constexpr uint8_t TARE_SAMPLE_COUNT = 20;
constexpr uint8_t MEDIAN_WINDOW = 5;
constexpr uint8_t STARTUP_DISCARD_READS = 4;

constexpr float ZERO_DEADBAND_GRAMS = 0.4f;
constexpr float LARGE_STEP_GRAMS = 60.0f;
constexpr uint32_t HX711_STALE_MS = 1500;
constexpr uint32_t BLE_NOTIFY_INTERVAL_MS = 200;
constexpr int32_t HX711_MIN_VALUE = -8388608;
constexpr int32_t HX711_MAX_VALUE = 8388607;

constexpr uint8_t MEASUREMENT_PACKET_VERSION = 1;
